package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
)

// writeDSHPatch regenerates the DSH bundle patch with this binary's real path and
// the chosen toolbox root, so a fresh install never needs hand-edited absolute
// paths. Re-running it after moving the binary keeps the profile in sync.
func writeDSHPatch(patchPath, binary, root string) error {
	body := strings.Join([]string{
		"# Generated by `toolbox -setup` on " + time.Now().Format("2006-01-02 15:04") + ".",
		"# Re-run it after moving the binary or changing the toolbox root.",
		"#",
		"# The bundle ships two rows: the manager page (this package) and the MCP",
		"# client that provides the agent tools. `!!js` is NOT evaluated inside",
		"# `config`, so every path here is a plain literal.",
		"- insert:",
		"    - id: dsh-toolbox",
		"      name: dsh-toolbox",
		"    - id: dsh-toolbox-mcp",
		`      name: "@deepseek-ai/dsh-mcp-client"`,
		"      config:",
		"        transport: stdio",
		"        serverName: toolbox",
		"        command: '" + yamlSingle(binary) + "'",
		"        args:",
		"          - '-mcp'",
		"          - '-root'",
		"          - '" + yamlSingle(root) + "'",
		"        toolCallTimeoutMs: 600000",
		"        failOnStartupError: true",
		"",
	}, "\n")

	absolute, err := filepath.Abs(patchPath)
	if err != nil {
		return err
	}
	if err := os.WriteFile(absolute, []byte(body), 0o644); err != nil {
		return fmt.Errorf("write %s: %w", absolute, err)
	}
	return nil
}

// yamlSingle escapes a value for a YAML single-quoted scalar.
func yamlSingle(value string) string {
	return strings.ReplaceAll(value, "'", "''")
}
